package com.greatleyposhley.professy.collaboration;
import com.greatleyposhley.professy.entities.*;import com.greatleyposhley.professy.repositories.UserAccountRepository;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.json.JsonMapper;import org.junit.jupiter.api.Test;import java.util.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class WorkspaceAppsTest {
 private WorkAccess access(JdbcTemplate jdbc){var a=spy(new WorkAccess(mock(UserAccountRepository.class),jdbc,mock(WorkspacePolicy.class)));var user=new UserAccount();user.setId(7L);user.setOrgId(3L);user.setOrgRole(OrgRole.SUPER_USER);doReturn(user).when(a).actor();doNothing().when(a).require(anyString());return a;}
 @Test void restrictedDocumentsDoNotGrantAdministratorsImplicitVisibility(){var jdbc=mock(JdbcTemplate.class);var access=access(jdbc);when(jdbc.queryForList(anyString(),eq(Long.class),any(Object[].class))).thenReturn(List.of());var docs=new DocumentAccess(access);assertThrows(ResponseStatusException.class,()->docs.require(3L,10L,false));verify(jdbc).queryForList(argThat(sql->sql.contains("p.created_by=? OR EXISTS")&&!sql.contains("OR ?=1")&&!sql.contains("='ORGANIZATION'")),eq(Long.class),eq(3L),eq(7L),eq(7L));verify(jdbc,never()).update(anyString(),any(Object[].class));}
 @Test void fileReadersCannotSaveContent(){var jdbc=mock(JdbcTemplate.class);var access=access(jdbc);when(jdbc.queryForList(contains("FROM workspace_files f"),any(Object[].class))).thenReturn(List.of(new LinkedHashMap<>(Map.of("id",9L,"owner_id",8L,"permission","VIEWER"))));var files=new WorkspaceFiles(access,JsonMapper.builder().build());assertThrows(ResponseStatusException.class,()->files.save("sheets",9,Map.of("revision",1,"title","Changed","content",Map.of("sheets",List.of()))));verify(jdbc,never()).update(anyString(),any(Object[].class));}
 @Test void staleVersionCannotOverwriteNewerWorkbook(){var jdbc=mock(JdbcTemplate.class);var access=access(jdbc);when(jdbc.queryForList(contains("FROM workspace_files f"),any(Object[].class))).thenReturn(List.of(new LinkedHashMap<>(Map.of("id",9L,"owner_id",7L,"permission",""))));when(jdbc.update(startsWith("UPDATE workspace_files SET"),any(Object[].class))).thenReturn(0);var files=new WorkspaceFiles(access,JsonMapper.builder().build());var error=assertThrows(ResponseStatusException.class,()->files.save("sheets",9,Map.of("revision",1,"title","Changed","content",Map.of("sheets",List.of()))));assertEquals(409,error.getStatusCode().value());verify(jdbc,never()).update(startsWith("INSERT INTO workspace_file_versions"),any(Object[].class));}
 @Test void negativeAgentSelectionNeverEntersHumanForeignKeys(){var access=access(mock(JdbcTemplate.class));var agents=mock(WorkspaceAgents.class);when(agents.row(12)).thenReturn(Map.of("id",12,"status","ACTIVE"));var actors=new TicketActors(access,agents,JsonMapper.builder().build());var body=new LinkedHashMap<String,Object>();body.put("assignee_user_id",-12);body.put("assignee",Map.of("id",-12));body.put("title","Task");var changes=actors.prepare("/api/tasks/5",body);assertNull(body.get("assignee_user_id"));assertNull(body.get("assignee"));assertEquals(-12L,changes.getFirst().assignments().get("assignee"));assertEquals(5,changes.getFirst().id());}
 @Test void explicitUnassignmentWinsOverStaleNestedAgentData(){var access=access(mock(JdbcTemplate.class));var actors=new TicketActors(access,mock(WorkspaceAgents.class),JsonMapper.builder().build());var body=new LinkedHashMap<String,Object>();body.put("assignee_user_id",null);body.put("assignee",Map.of("id",-12));var changes=actors.prepare("/api/epics/create",body);assertEquals(0L,changes.getFirst().assignments().get("assignee"));assertNull(body.get("assignee"));}
 @Test void bulkCreationCapturesEachAgentAssignment(){var access=access(mock(JdbcTemplate.class));var agents=mock(WorkspaceAgents.class);when(agents.row(12)).thenReturn(Map.of("status","ACTIVE"));var actors=new TicketActors(access,agents,JsonMapper.builder().build());var first=new LinkedHashMap<String,Object>(Map.of("assignee_user_id",-12));var second=new LinkedHashMap<String,Object>(Map.of("assignee_user_id",7));var changes=actors.prepare("/api/stories/bulk-create",List.of(first,second));assertEquals(2,changes.size());assertNull(first.get("assignee_user_id"));assertEquals(7L,second.get("assignee_user_id"));}
 @Test void agentMustBeActiveAndInTheTicketProject(){var jdbc=mock(JdbcTemplate.class);var access=access(jdbc);doReturn(Map.of("work_project_id",4L)).when(access).ticket("TASK",5,false);var agents=mock(WorkspaceAgents.class);when(agents.projects(12)).thenReturn(List.of(9L));var actors=new TicketActors(access,agents,JsonMapper.builder().build());assertThrows(IllegalArgumentException.class,()->actors.finish(List.of(new TicketActors.Change("TASK",5,Map.of("assignee",-12L))),new byte[0]));verify(jdbc,never()).update(anyString(),any(Object[].class));}
 @Test void meetingSignalsAreNotVisibleToUninvitedUsers(){var jdbc=mock(JdbcTemplate.class);var access=access(jdbc);when(jdbc.queryForList(contains("FROM workspace_meetings m LEFT JOIN"),any(Object[].class))).thenReturn(List.of());var meetings=new WorkspaceMeetings(access,mock(WorkspaceAgents.class),JsonMapper.builder().build());assertThrows(ResponseStatusException.class,()->meetings.signals(2,0));verify(jdbc,never()).update(anyString(),any(Object[].class));}
}
